using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;
using Microsoft.EntityFrameworkCore.ChangeTracking;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1 – Discriminator property renamed to "$type" in EF 9.
            // Preserve the old property name so existing documents are still found.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2 – id value no longer includes the discriminator prefix.
            // Old format: "Blog|<key>".  Preserve it with a shadow‑property key.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGeneratorFactory<BlogIdGeneratorFactory>();
            entity.HasKey("__id");

            // Map the entity Id to a non‑id JSON property so it stays usable.
            entity.Property(b => b.Id).ToJsonProperty("Id");

            // Breaking change 3 – HasIndex now throws for the Cosmos provider.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}

// Generates the old-format Cosmos "id" value: "Blog|<key>"
class BlogIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Blog|{entry.Property("Id").CurrentValue}";
}

class BlogIdGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(Microsoft.EntityFrameworkCore.Metadata.IProperty property, Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new BlogIdGenerator();
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

